def transform(grid):
    g = np.array(grid)
    bg = background(g)
    objs = objects(g, bg=bg)
    fi = max(range(len(objs)), key=lambda i: objs[i]["size"])
    frame = objs[fi]
    fc = frame["colour"]
    y0, x0, y1, x1 = frame["box"]

    def norm(cells):
        my = min(c[0] for c in cells); mx = min(c[1] for c in cells)
        return frozenset((y - my, x - mx) for y, x in cells)

    key_idx = set()
    for i, o in enumerate(objs):
        if i == fi or o["colour"] == fc:
            continue
        if all(y0 <= y <= y1 and x0 <= x <= x1 for y, x in o["cells"]):
            key_idx.add(i)
    key_shapes = {norm(objs[i]["cells"]) for i in key_idx}

    out = g.copy()
    for i, o in enumerate(objs):
        if i == fi or i in key_idx or o["colour"] == fc:
            continue
        if norm(o["cells"]) in key_shapes:
            for y, x in o["cells"]:
                out[y, x] = fc
            emit(out, f"Object of colour {o['colour']} has exactly the key's shape (same orientation); recolour it to the frame colour {fc}.")
    emit(out, "Final grid: every copy of the key shape outside the frame now has the frame colour.")
    return out
